{
  "contract": "DLAND",
  "closure": {
    "site_function": "retrieve_marketing",
    "site_call": ".call",
    "functions": [
      "retrieve_marketing",
      "retrieve_president",
      "retrieve_development",
      "retrieve_coder",
      "avoid_locks"
    ],
    "justification": "All functions that write to _ethBal or any balance involved in the target property must be included. 'avoid_locks' also writes to _ethBal, so it must be part of the closure. These functions can potentially be called during the reentrant call and affect the exposure invariant."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "retrieve_marketing",
      "retrieve_president",
      "retrieve_development",
      "retrieve_coder",
      "avoid_locks"
    ],
    "nesting_bound": {
      "retrieve_marketing": 1
    }
  },
  "phases": {
    "function": "retrieve_marketing",
    "pre": {
      "name": "pre",
      "from_marker": "retrieve_marketing:ENTRY",
      "to_marker": ".call:ENTRY"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": ".call:ENTRY",
      "to_marker": ".call:EXIT"
    },
    "post": {
      "name": "post",
      "from_marker": ".call:EXIT",
      "to_marker": "retrieve_marketing:EXIT"
    },
    "linearization_point": "retrieve_marketing:EXIT"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount mid-transfer during callback",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "president_balance + marketing_balance + development_balance + coder_balance <= _ethBal + inFlight",
    "stable_formula": "president_balance + marketing_balance + development_balance + coder_balance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "president_balance + marketing_balance + development_balance + coder_balance <= _ethBal",
    "rule": "During exposure, include inFlight to account for in-flight changes."
  }
}
